  text: {
bn: [
"শ্বাস-প্রশ্বাস সর্বদাই জীবনদায়ী; Quism-এর স্বাভাবিক শ্বাস উৎসারিত হয় অচেতন ও সুপ্ত বিশ্রামের নীরব অন্তরালয় থেকে; যেখানে জীবনের নিজস্ব ছন্দ এবং প্রকৃতির সুষমা একাকার হয়ে প্রবাহিত হয়; সেই শান্ত প্রবাহে দেহ আপন নিয়মে সুষমায় স্থিত থাকে, চেতন-মন অচেতনের গভীর প্রশান্তিকে স্পর্শ করে, আর প্রতিটি নিঃশ্বাসে জীবন ও প্রকৃতির অবিচ্ছিন্ন মিলন নব অনুরণনে জেগে ওঠে; সময়ের প্রতিটি স্পন্দন যেন সেই নীরব শ্বাসেরই প্রতিধ্বনি; Quism-এর স্বাভাবিক শ্বাস তাই কেবল শ্বাস নয়, সুপ্ত বিশ্রাম থেকে জীবন-জাগরণের প্রথম স্পন্দন; Quism → Qu + ism;",
],

en: [
"Breathing is ever life-giving; in Quism, natural breathing emerges from the silent realm of unconscious and latent rest; where the innate rhythm of life and the harmony of nature flow as one; within this tranquil current, the body abides in its own balance, the conscious mind touches the profound serenity of the unconscious, and every breath awakens the timeless union of life and nature in renewed resonance; every pulse of time echoes this silent breath; thus, natural breathing in Quism is not merely breath, but the first pulse of life's awakening from latent rest; Quism → Qu + ism;",
],

hi: [
"श्वास-प्रश्वास सदैव जीवनदायी है; Quism में स्वाभाविक श्वास अचेतन और सुप्त विश्राम के मौन अंतराल से उद्भूत होती है; जहाँ जीवन की स्वाभाविक लय और प्रकृति का संतुलन एक प्रवाह बन जाते हैं; उसी शांत प्रवाह में शरीर अपने स्वभावगत संतुलन में स्थित रहता है, चेतन-मन अचेतन की गहन शांति का स्पर्श करता है, और प्रत्येक श्वास के साथ जीवन तथा प्रकृति का अविच्छिन्न मिलन नव अनुनाद में जागृत होता है; समय का प्रत्येक स्पंदन मानो उसी मौन श्वास की प्रतिध्वनि है; इसलिए Quism की स्वाभाविक श्वास केवल श्वास नहीं, बल्कि सुप्त विश्राम से जीवन-जागरण का प्रथम स्पंदन है; Quism → Qu + ism;",
],

sa: [
"श्वास-प्रश्वासः सदा जीवनदायकः; Quism-दर्शने स्वाभाविकः श्वासः अचेतनस्य सुप्तविश्रामस्य मौनान्तरालयात् उद्भवति; यत्र जीवनस्य स्वाभाविकी लयः प्रकृतेः सामञ्जस्येन सह एकप्रवाहत्वेन वहति; तस्मिन् शान्तप्रवाहे शरीरं स्वसमत्वे स्थितं भवति, चेतनमनः अचेतनस्य गम्भीरप्रशान्तिं स्पृशति, प्रत्येकेन श्वासेन जीवनस्य प्रकृतेश्च अविच्छिन्नं मिलनं नवानुनादेन जागरूकं भवति; कालस्य प्रत्येकः स्पन्दः तस्य मौनश्वासस्यैव प्रतिध्वनिरिव भवति; अतः Quism-दर्शने स्वाभाविकः श्वासः केवलं श्वासः न, किन्तु सुप्तविश्रामात् जीवनजागरणस्य प्रथमः स्पन्दः; Quism → Qu + ism;",
],
},
