hi: [
"स्वप्न का स्थान और मुक्तस्थान परम सत्ता के अंतर्गत अस्तित्व का प्रतिबिंब है, जो शून्यता के उस विस्तृत अंतराल से परिपूर्ण है, जहाँ योग-साधना का बीज और उसका पोषण करने वाली पोषकता, श्वास की निःशब्दता, समय और सीमाएँ धीरे-धीरे मिलकर एक मुक्त संभावना का क्षेत्र निर्मित करती हैं; स्थान स्वप्न के रूप को धारण करता है और मुक्तस्थान उस रूप की सीमा को पार कर शून्यता की ओर विस्तृत होता है, जहाँ कोई निश्चित बंधन नहीं है, फिर भी असीम संभावनाओं की मौन उपस्थिति बनी रहती है; Quism के दर्शन में स्थान और मुक्तस्थान स्वप्न और वास्तविक जीवनयात्रा का एक ही परिपक्व स्तर है, जहाँ शून्यगर्भ से निःशब्दता का ध्वनि पुनः शून्यता के विस्तार में लौटता है और जीवन अपने असीम अस्तित्व को अनुभव करता है;"
],

sa: [
"स्वप्नस्य स्थानं मुक्तस्थानं च परमसत्तायाः अन्तर्गतस्य अस्तित्वस्य प्रतिबिम्बम् अस्ति, यत् शून्यतायाः विस्तीर्णेन अन्तरालेन परिपूर्णम् अस्ति, यत्र योगसाधनायाः बीजं तस्य पोषणं च, श्वासस्य निःशब्दता, कालः सीमाश्च शनैः शनैः सम्मिलित्वा मुक्तसम्भावनायाः क्षेत्रं निर्मिमन्ति; स्थानं स्वप्नस्य रूपं धारयति, मुक्तस्थानं च तस्य रूपस्य सीमाम् अतिक्रम्य शून्यतां प्रति विस्तरति, यत्र किमपि निश्चितं बन्धनं नास्ति, तथापि असीमसम्भावनानां मौनसत्ता तिष्ठति; Quism-दर्शने स्थानं मुक्तस्थानं च स्वप्नस्य वास्तविकजीवनयात्रायाश्च एकमेव परिपक्वं स्तरम् अस्ति, यत्र शून्यगर्भात् निःशब्दतायाः ध्वनिः पुनः शून्यतायाः विस्तारे प्रत्यावर्तते, जीवनं च स्वस्य असीमम् अस्तित्वम् अनुभूयते;"
],
