  text: {
bn: [
"জঠরাগ্নি: শরীরের মৌলিক পাচক অগ্নি, যা জীবন-সাম্য, প্রাণশক্তি ও দেহ-সংরক্ষণের অন্যতম ভিত্তি; সৌরজগত যেমন নিজস্ব শক্তির ভারসাম্যে স্থিত থাকে, তেমনি জঠরাগ্নিও শরীরের অভ্যন্তরীণ সামঞ্জস্য রক্ষা করে; Quism-এর দৃষ্টিতে অপ্রয়োজনীয় ও তাৎক্ষণিক খাদ্যাভ্যাস জঠরাগ্নির স্বাভাবিক কার্যপ্রবাহে বিঘ্ন সৃষ্টি করে, যার ফলে দেহের স্বাভাবিক রোগ-প্রতিরোধ ক্ষমতা ক্রমশ দুর্বল হতে পারে;",
],

en: [
"Digestive Fire: The fundamental digestive fire of the body, forming one of the essential foundations of life's balance, life-force, and bodily preservation; Just as the solar system is sustained through the harmony of its own energy, the digestive fire maintains the body's inner equilibrium; In Quism, unnecessary and impulsive eating habits disturb the natural function of the digestive fire, gradually weakening the body's innate immune resilience;",
],

hi: [
"जठराग्नि: शरीर की मूल पाचन-अग्नि, जो जीवन-संतुलन, प्राणशक्ति तथा शरीर-संरक्षण के प्रमुख आधारों में से एक है; जैसे सौरमंडल अपनी ऊर्जा के संतुलन से स्थिर रहता है, वैसे ही जठराग्नि शरीर के आंतरिक संतुलन को बनाए रखती है; क्विज़्म के अनुसार अनावश्यक एवं असंयमित भोजन-अभ्यास जठराग्नि के स्वाभाविक कार्य में बाधा उत्पन्न करते हैं, जिससे शरीर की प्राकृतिक रोग-प्रतिरोधक क्षमता धीरे-धीरे क्षीण हो सकती है;",
],

sa: [
"जठराग्निः: शरीरस्य मूलपाचनाग्निः, या जीवनसन्तुलनस्य, प्राणशक्तेः, शरीरसंरक्षणस्य च प्रमुखाधारः अस्ति; यथा सौरमण्डलं स्वकीयशक्तेः समत्वेन स्थितिं धारयति, तथा जठराग्निः शरीरस्य आन्तरिकसमतां रक्षति; क्विज्मस्य दृष्ट्या अनावश्यकम् असंयतं च भोजनाचारः जठराग्नेः स्वाभाविककार्ये विघ्नं जनयति, येन शरीरस्य सहजव्याधिप्रतिरोधशक्तिः शनैः शनैः क्षीयते;",
],
 },
