"भूमिगत अग्निशिखा प्रकृति की अंतर्निहित सुप्त शक्ति का प्रतीक है, जहाँ आंतों का पाचन, पोषक तत्त्वों का अवशोषण तथा मस्तिष्क की तंत्रिका कोशिकाओं का संबंध ऊष्मा, दाब और रूपांतरण के माध्यम से नवसृष्टि की संभावना को सुप्त अवस्था में सुरक्षित रखता है; Quism के दर्शन में यह आंतरिक अग्निशिखा गहरी श्वास-प्रश्वास के द्वारा स्थिर होती है, जहाँ मौन परिवर्तन, सहनशीलता और विकास का आधार उचित समय पर नए उत्कर्ष का आरंभ करता है;",
