  text: {
bn: [
"পুনঃসৃজনশীল গর্ভ হলো অবচেতনের সৃজনশীল সম্ভাবনা, যেখানে অবচেতনের আত্মপ্রকাশ অন্তর্জাগরণের আধ্যাত্মিক পথনির্দেশ হয়ে নীরব চিন্তা, স্বপ্ন ও অনুভূতির মাধ্যমে নতুন সৃষ্টির বীজ ধারণ করে; Quism-এর দর্শনে এই গর্ভ সৃষ্টির বীজসত্তা প্রকাশ ও বটবৃক্ষের ন্যায় স্থির অন্তঃশক্তির প্রতীক, যা আত্ম-উপলব্ধির গভীরে সুপ্ত সৃজনশীল শক্তিকে জাগ্রত করে; যেখানে প্রতিটি প্রতিফলন নতুন জীবন, নতুন চিন্তা ও নতুন সম্ভাবনার স্বাভাবিক সূচনা হয়ে বিকশিত হয়;",
],

en: [
"Recreative Womb symbolizes the creative potential of the subconscious, where the self-expression of the subconscious becomes the spiritual guidance of inner awakening, nurturing the seeds of new creation through silent thought, dreams, and feelings; In Quism, this womb represents the manifestation of the seed-essence of creation and the symbol of stable inner strength, like a banyan tree, awakening the dormant creative power within the depths of self-realization; where every reflection naturally unfolds into new life, new thought, and new possibilities;",
],

hi: [
"पुनःसृजनशील गर्भ अवचेतन की सृजनात्मक संभावना का प्रतीक है, जहाँ अवचेतन की आत्म-अभिव्यक्ति अंतर्जागरण का आध्यात्मिक मार्गदर्शन बनकर मौन विचार, स्वप्न और अनुभूतियों के माध्यम से नई सृष्टि के बीज धारण करती है; Quism के दर्शन में यह गर्भ सृष्टि की बीजसत्ता की अभिव्यक्ति तथा वटवृक्ष के समान स्थिर अंतःशक्ति का प्रतीक है, जो आत्मबोध की गहराइयों में सुप्त सृजनात्मक शक्ति को जागृत करता है; जहाँ प्रत्येक प्रतिबिंब स्वाभाविक रूप से नए जीवन, नए विचार और नई संभावनाओं के रूप में विकसित होता है;",
],

sa: [
"पुनःसृजनशीलगर्भः अवचेतनस्य सृजनात्मकसम्भावनायाः प्रतीकः, यत्र अवचेतनस्य आत्मप्रकाशः अन्तर्जागरणस्य आध्यात्मिकमार्गदर्शनं भूत्वा मौनचिन्तनैः, स्वप्नैः, अनुभूतिभिश्च नूतनसृष्टेः बीजानि धारयति; Quism-दर्शने अयं गर्भः सृष्टेः बीजसत्तायाः अभिव्यक्तेः वटवृक्षवत् स्थिरान्तःशक्तेः च प्रतीकः, यः आत्मोपलब्धेः गम्भीरतायां सुप्तां सृजनात्मकशक्तिं जागरयति; यत्र प्रत्येकं प्रतिबिम्बं स्वाभाविकतया नूतनजीवनं, नूतनचिन्तनं नूतनसम्भावनाश्च विकसितानि भवन्ति;",
],
 },
