hi: [
  "शरीर चेतना की आदिभूमि है और सूक्ष्म देह अंतःस्वरूप का प्रतिबिंब है, जो शक्ति और प्राणशक्ति के रूपांतरण में चेतना के साक्षी के रूप में स्थित रहती है, जहाँ वह जीवन-प्रकृति तथा सचेतन-अचेतन के प्रवाह को प्रत्यक्ष देखती है और उस सूक्ष्म प्रतिबिंब को दृश्य रूप में धारण करती है; Quism के दर्शन में प्रतिबिंब स्वप्न का एक कल्पनालोक है, जो जीवन-चेतना की बाह्य सृष्टि के माध्यम से अंतर्निहित अतिचेतना की एक अभिव्यक्ति है, जहाँ प्रत्येक स्पंदन का दृश्य रूप क्रमशः अपने सूक्ष्म अर्थ में लौट आता है; सूक्ष्म देह काल, परिवेश और मन-बुद्धि के अविच्छिन्न चक्र के रूप में आत्मा की चेतना को धारण करती है और जीवन को जाग्रत करती है;"
],

sa: [
  "शरीरं चेतनायाः आदिभूमिः तथा सूक्ष्मदेहः अन्तःस्वरूपस्य प्रतिबिम्बः, यः शक्तेः प्राणशक्तेश्च रूपान्तरणे चेतनायाः साक्षी भवति, यत्र सः जीवन-प्रकृत्योः सचेतन-अचेतनयोश्च प्रवाहं प्रत्यक्षं पश्यति तथा तं सूक्ष्मप्रतिबिम्बं दृश्यरूपे धारयति; Quism-दर्शने प्रतिबिम्बं स्वप्नस्य एकः कल्पनालोकः, यः जीवन-चेतनायाः बाह्यसृष्टेः माध्यमेन अन्तर्निहितातिचेतनायाः एकं प्रकाशनम्, यत्र प्रत्येकस्य स्पन्दनस्य दृश्यरूपं क्रमेण स्वसूक्ष्मार्थं प्रति प्रत्यागच्छति; सूक्ष्मदेहः काल-परिवेश-मनःबुद्धेः अविच्छिन्नचक्रं धारयन् आत्मनः चेतनां वहति तथा जीवनं जागरयति;"
],
