"ধ্যান হলো হৃদস্পন্দনে জীবনতরঙ্গের নীরব অনুরণন, যেখানে জীবন উৎসের অনুশাসন চেতনার গভীরে প্রতিফলিত হয়; Quism-এর ভাষায় ধ্যান হলো অচেতন-স্বপ্নের উৎস, কার্যকারণ সম্পর্কের নিরন্তর অনুসন্ধান এবং তার সামঞ্জস্য ও অসামঞ্জস্যের নীরব পর্যবেক্ষণ; চেতনার আত্মসংযম, অন্তর্জাগরণ ও জীবনচর্চার স্বাভাবিক ধারাবাহিকতায় মন নীরব হয়ে উৎসের দিকে অভিমুখী হয়; হৃদস্পন্দনে জীবনতরঙ্গ, মনের অনুরণন ও নীরব ধ্যান—জীবনকে তার উৎসের স্বাভাবিক সামঞ্জস্যে প্রতিষ্ঠিত করে;",
