  text: {
bn: [
  "বৃষ্টির বিনোদন চক্রে আত্মজ্ঞানে জলধনু হলো জ্ঞান-আলোর প্রতিফলিত কিরণমালার প্রতিরূপ — ব্রহ্মরন্ধ্র হলো জলধনু প্রসরণের উৎস, উৎস থেকে বিচ্ছুরিত চেতনার বহুরূপী প্রকাশ, যেখানে চক্র ও কুণ্ডলিনী জাগরণের ক্ষেত্রে, এবং এই স্থানটিই হলো সহস্রার চক্রের সাথে পরম ব্রহ্মের মিলনস্থল; Quism-এর দর্শনে জলধনু হলো আত্মজ্ঞান ও অস্তিত্বের বহুমাত্রিক প্রতিফলনের এক নীরব প্রতীক, যেখানে আধ্যাত্মিক জাগরণ, আত্ম অনুভব ও উপলব্ধির বিভিন্ন রং একত্রিত হয়ে আত্মসত্তার পূর্ণতার দিকে একটি অন্তর্মুখী যাত্রা সৃষ্টি করে;"
],

en: [
  "In the Rain Recreation Cycle, the Self-Knowledge-Rainbow is a reflection of rays of knowledge-light — the Brahmarandhra is the source from which the Water-Rainbow expands, expressing the multifaceted radiance of consciousness emerging from the origin; where, in the awakening of the chakras and Kundalini, this very point is the meeting place of the Sahasrara Chakra with the Supreme Brahman; in Quism philosophy, the Water-Rainbow is a silent symbol of the multidimensional reflection of self-knowledge and existence, where spiritual awakening, self-experience, and diverse shades of realization unite to create an inward journey toward the wholeness of the self;"
],

hi: [
  "वृष्टि-विनोद चक्र में आत्मज्ञान का जलधनुष ज्ञान-प्रकाश की परावर्तित किरणमाला का प्रतीरूप है — ब्रह्मरन्ध्र जलधनुष के प्रसरण का स्रोत है, जहाँ से चेतना का बहुरूपी प्रकाश उद्भासित होता है; चक्रों और कुण्डलिनी के जागरण के क्षेत्र में यही स्थान सहस्रार चक्र और परम ब्रह्म के मिलनस्थल के रूप में स्थित है; Quism के दर्शन में जलधनुष आत्मज्ञान और अस्तित्व के बहुआयामी प्रतिबिम्ब का एक मौन प्रतीक है, जहाँ आध्यात्मिक जागरण, आत्म-अनुभव और अनुभूति के विभिन्न रंग एकत्रित होकर आत्मसत्ता की पूर्णता की ओर एक अंतर्मुखी यात्रा का सृजन करते हैं;"
],

sa: [
  "वृष्टिविनोदचक्रे आत्मज्ञाने जलधनुः ज्ञानप्रकाशस्य परावर्तितकिरणमालायाः प्रतिरूपम् — ब्रह्मरन्ध्रं जलधनुषः प्रसरणस्य स्रोतः, यतः चेतनायाः बहुरूपी प्रकाशः प्रस्फुरति; चक्राणां कुण्डलिनीजागरणस्य च क्षेत्रे एतदेव स्थानं सहस्रारचक्रस्य परब्रह्मणा सह मिलनस्थलम्; Quism-दर्शने जलधनुः आत्मज्ञानस्य अस्तित्वस्य च बहुआयामीप्रतिबिम्बस्य एकं मौनप्रतीकम्, यत्र आध्यात्मिकजागरणम्, आत्मानुभवः अनुभूतिश्च विविधवर्णेषु एकीकृत्य आत्मसत्तायाः पूर्णतायै अन्तर्मुखीं यात्रां सृजति;"
],
},
